ALTER TABLE public.real_estate_calculations ADD COLUMN IF NOT EXISTS analysis_question text, ADD COLUMN IF NOT EXISTS valuation_date date, ADD COLUMN IF NOT EXISTS time_horizon_months integer;
ALTER TABLE public.calculation_scenarios ADD COLUMN IF NOT EXISTS business_case text, ADD COLUMN IF NOT EXISTS intervention text, ADD COLUMN IF NOT EXISTS expansion_subtype text, ADD COLUMN IF NOT EXISTS exploitation_mode text, ADD COLUMN IF NOT EXISTS disposition text, ADD COLUMN IF NOT EXISTS taxonomy_schema_version integer;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='real_estate_calculations_analysis_question_check' AND conrelid='public.real_estate_calculations'::regclass) THEN ALTER TABLE public.real_estate_calculations ADD CONSTRAINT real_estate_calculations_analysis_question_check CHECK (analysis_question IS NULL OR length(btrim(analysis_question)) BETWEEN 1 AND 2000); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='real_estate_calculations_time_horizon_check' AND conrelid='public.real_estate_calculations'::regclass) THEN ALTER TABLE public.real_estate_calculations ADD CONSTRAINT real_estate_calculations_time_horizon_check CHECK (time_horizon_months IS NULL OR time_horizon_months BETWEEN 1 AND 1200); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_business_case_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_business_case_check CHECK (business_case IS NULL OR business_case IN ('legacy_generic','income_investment','value_add','redevelopment','new_development','land_development','portfolio_optimization','operating_asset','capital_restructuring','asset_disposal')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_intervention_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_intervention_check CHECK (intervention IS NULL OR intervention IN ('none','maintain','renovate','sustainability_upgrade','split','transform','expand','demolish_newbuild','site_development')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_expansion_subtype_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_expansion_subtype_check CHECK (expansion_subtype IS NULL OR expansion_subtype IN ('rooftop_addition','horizontal_extension','new_volume_on_plot','interior_densification','other')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_exploitation_mode_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_exploitation_mode_check CHECK (exploitation_mode IS NULL OR exploitation_mode IN ('vacant','rental','owner_occupied','operating_business','temporary_use','mixed','undecided')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_disposition_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_disposition_check CHECK (disposition IS NULL OR disposition IN ('hold','sell_as_whole','sell_unit','sell_component','sale_and_leaseback','deferred','undecided')); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_taxonomy_schema_version_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_taxonomy_schema_version_check CHECK (taxonomy_schema_version IS NULL OR taxonomy_schema_version > 0); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_expansion_consistency_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_expansion_consistency_check CHECK (expansion_subtype IS NULL OR intervention='expand'); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='calculation_scenarios_taxonomy_atomic_check' AND conrelid='public.calculation_scenarios'::regclass) THEN ALTER TABLE public.calculation_scenarios ADD CONSTRAINT calculation_scenarios_taxonomy_atomic_check CHECK ((taxonomy_schema_version IS NULL AND business_case IS NULL AND intervention IS NULL AND expansion_subtype IS NULL AND exploitation_mode IS NULL AND disposition IS NULL) OR (taxonomy_schema_version IS NOT NULL AND business_case IS NOT NULL AND intervention IS NOT NULL AND exploitation_mode IS NOT NULL AND disposition IS NOT NULL)); END IF; END $$;
ALTER TABLE public.sell_off_units ADD COLUMN IF NOT EXISTS allocation_percentage numeric(7,4), ADD COLUMN IF NOT EXISTS development_start_month integer, ADD COLUMN IF NOT EXISTS development_end_month integer, ADD COLUMN IF NOT EXISTS rent_start_month integer, ADD COLUMN IF NOT EXISTS hold_exit_month integer, ADD COLUMN IF NOT EXISTS allocation_timing_schema_version integer;
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_allocation_percentage_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_allocation_percentage_check CHECK (allocation_percentage is null or (allocation_percentage > 0 and allocation_percentage <= 100)); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_development_start_month_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_development_start_month_check CHECK (development_start_month is null or development_start_month between 0 and 1200); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_development_end_month_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_development_end_month_check CHECK (development_end_month is null or development_end_month between 0 and 1200); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_rent_start_month_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_rent_start_month_check CHECK (rent_start_month is null or rent_start_month between 0 and 1200); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_expected_sale_period_months_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_expected_sale_period_months_check CHECK (expected_sale_period_months is null or expected_sale_period_months between 0 and 1200); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_hold_exit_month_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_hold_exit_month_check CHECK (hold_exit_month is null or hold_exit_month between 0 and 1200); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_development_period_order_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_development_period_order_check CHECK (development_start_month is null or development_end_month is null or development_end_month >= development_start_month); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_rent_after_development_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_rent_after_development_check CHECK (development_end_month is null or rent_start_month is null or rent_start_month >= development_end_month); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_sale_after_development_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_sale_after_development_check CHECK (development_end_month is null or expected_sale_period_months is null or expected_sale_period_months >= development_end_month); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_hold_exit_after_rent_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_hold_exit_after_rent_check CHECK (rent_start_month is null or hold_exit_month is null or hold_exit_month >= rent_start_month); END IF; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='public.sell_off_units'::regclass AND conname='sell_off_units_allocation_timing_version_check') THEN ALTER TABLE public.sell_off_units ADD CONSTRAINT sell_off_units_allocation_timing_version_check CHECK (allocation_timing_schema_version is null or (allocation_timing_schema_version > 0 and allocation_percentage is not null)); END IF; END $$;
alter table public.scenario_costs add column if not exists cashflow_timing_method text null, add column if not exists cashflow_start_month integer null, add column if not exists cashflow_end_month integer null, add column if not exists cashflow_payment_month integer null, add column if not exists cashflow_timing_schema_version integer null;
alter table public.scenario_costs drop constraint if exists scenario_costs_cashflow_timing_method_check, add constraint scenario_costs_cashflow_timing_method_check check (cashflow_timing_method is null or cashflow_timing_method in ('single','linear')), drop constraint if exists scenario_costs_cashflow_start_month_check, add constraint scenario_costs_cashflow_start_month_check check (cashflow_start_month is null or cashflow_start_month between 0 and 1200), drop constraint if exists scenario_costs_cashflow_end_month_check, add constraint scenario_costs_cashflow_end_month_check check (cashflow_end_month is null or cashflow_end_month between 0 and 1200), drop constraint if exists scenario_costs_cashflow_payment_month_check, add constraint scenario_costs_cashflow_payment_month_check check (cashflow_payment_month is null or cashflow_payment_month between 0 and 1200), drop constraint if exists scenario_costs_cashflow_timing_schema_version_check, add constraint scenario_costs_cashflow_timing_schema_version_check check (cashflow_timing_schema_version is null or cashflow_timing_schema_version = 1), drop constraint if exists scenario_costs_cashflow_timing_chronology_check, add constraint scenario_costs_cashflow_timing_chronology_check check (cashflow_start_month is null or cashflow_end_month is null or cashflow_end_month >= cashflow_start_month), drop constraint if exists scenario_costs_cashflow_timing_contract_check, add constraint scenario_costs_cashflow_timing_contract_check check ((cashflow_timing_method is null and cashflow_start_month is null and cashflow_end_month is null and cashflow_payment_month is null and cashflow_timing_schema_version is null) or (cashflow_timing_schema_version = 1 and ((cashflow_timing_method='single' and cashflow_payment_month is not null and cashflow_start_month is null and cashflow_end_month is null) or (cashflow_timing_method='linear' and cashflow_start_month is not null and cashflow_end_month is not null and cashflow_payment_month is null))));
alter table public.calculation_scenarios add column if not exists dcf_discount_rate_pct numeric(8,4) null, add column if not exists dcf_discount_rate_source text null, add column if not exists dcf_discount_rate_notes text null, add column if not exists dcf_schema_version integer null;
alter table public.calculation_scenarios drop constraint if exists calculation_scenarios_dcf_discount_rate_check, add constraint calculation_scenarios_dcf_discount_rate_check check (dcf_discount_rate_pct is null or dcf_discount_rate_pct between 0 and 100), drop constraint if exists calculation_scenarios_dcf_schema_version_check, add constraint calculation_scenarios_dcf_schema_version_check check (dcf_schema_version is null or dcf_schema_version = 1), drop constraint if exists calculation_scenarios_dcf_contract_check, add constraint calculation_scenarios_dcf_contract_check check ((dcf_discount_rate_pct is null and dcf_discount_rate_source is null and dcf_discount_rate_notes is null and dcf_schema_version is null) or (dcf_discount_rate_pct is not null and dcf_discount_rate_source is not null and btrim(dcf_discount_rate_source) <> '' and dcf_schema_version = 1));